    this.playQuestionNum = document.getElementById('play-question-num');
    this.playQuestionType = document.getElementById('play-question-type');
    this.timerStatLabel = document.getElementById('timer-stat-label');
    this.timerDisplay = document.getElementById('timer-display');
    this.timerGaugeFill = document.getElementById('timer-gauge-fill');
    this.playUserDisplay = document.getElementById('play-user-display');
    this.mapGameCard = document.getElementById('map-game-card');
    this.feedbackBanner = document.getElementById('feedback-banner');
    this.mapOverlaysLayer = document.getElementById('map-overlays-layer');
    this.previewOverlay = document.getElementById('preview-overlay');
    this.btnStartQuestion = document.getElementById('btn-start-question');
    this.btnSubmitAnswer = document.getElementById('btn-submit-answer');
    this.btnGiveup = document.getElementById('btn-giveup');

    // 결과 UI
    this.resultIcon = document.getElementById('result-icon');
