    this.resultDesc = document.getElementById('result-desc');
    this.resultTimeVal = document.getElementById('result-time-val');
    this.resultLeftVal = document.getElementById('result-left-val');
    this.resultUnlockVal = document.getElementById('result-unlock-val');
    this.resultNextTip = document.getElementById('result-next-tip');
    this.btnNextStage = document.getElementById('btn-next-stage');
